validator:
function validate(input) {
  const [{ CoffeeShop = [] }] = input;
  const seen = new Set();
  for (const [id] of CoffeeShop) {
    if (id === null) return 'Every row needs an id.';
    if (seen.has(id)) return `id ${id} appears twice.`;
    seen.add(id);
  }
  if (CoffeeShop.length && CoffeeShop[0][1] === null) return 'The first row must have a drink.';
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const drinks = ['Rum and Coke', 'St Germain Spritz', 'Orange Margarita', 'Latte', 'Mojito'];
  const n = small ? Math.floor(rand() * 9) : 2000;
  const ids = [];
  for (let i = 1; i <= (small ? 12 : 2000); i++) ids.push(i);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const CoffeeShop = [];
  for (let i = 0; i < n; i++) {
    const drink = i > 0 && rand() < 0.45 ? null : drinks[Math.floor(rand() * drinks.length)];
    CoffeeShop.push([ids[i], drink]);
  }
  return [{ CoffeeShop }];
}
